public class SupplyCrateTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object safe(java.util.function.Supplier<Object> body) {
        try {
            return body.get();
        } catch (Throwable t) {
            return "<threw " + t.getClass().getSimpleName() + ">";
        }
    }

    static SupplyCrate stocked() {
        SupplyCrate crate = new SupplyCrate(20);
        crate.add("rope", 3);
        crate.add("axe", 2);
        return crate;
    }

    public static void main(String[] args) {
        check("add reports success", Boolean.TRUE,
                safe(() -> new SupplyCrate(10).add("rope", 3)));
        check("countOf after two adds of the same item", 5,
                safe(() -> {
                    SupplyCrate crate = new SupplyCrate(10);
                    crate.add("rope", 3);
                    crate.add("rope", 2);
                    return crate.countOf("rope");
                }));
        check("countOf an item never added", 0,
                safe(() -> stocked().countOf("tent")));
        check("totalUnits", 5, safe(() -> stocked().totalUnits()));
        check("remainingSpace", 15, safe(() -> stocked().remainingSpace()));
        check("zero quantity is refused", "false|0",
                safe(() -> {
                    SupplyCrate crate = new SupplyCrate(10);
                    boolean ok = crate.add("rope", 0);
                    return ok + "|" + crate.totalUnits();
                }));
        check("over-capacity add is refused and changes nothing", "false|5",
                safe(() -> {
                    SupplyCrate crate = stocked();
                    boolean ok = crate.add("tent", 16);
                    return ok + "|" + crate.totalUnits();
                }));
        check("add that exactly fills the crate is allowed", "true|20",
                safe(() -> {
                    SupplyCrate crate = stocked();
                    boolean ok = crate.add("tent", 15);
                    return ok + "|" + crate.totalUnits();
                }));
        check("removing more than held is refused", "false|3",
                safe(() -> {
                    SupplyCrate crate = stocked();
                    boolean ok = crate.remove("rope", 4);
                    return ok + "|" + crate.countOf("rope");
                }));
        check("removing everything drops the entry", "[axe]",
                safe(() -> {
                    SupplyCrate crate = stocked();
                    crate.remove("rope", 3);
                    return crate.itemNames().toString();
                }));
        check("itemNames is sorted", "[axe, rope, tent]",
                safe(() -> {
                    SupplyCrate crate = stocked();
                    crate.add("tent", 1);
                    return crate.itemNames().toString();
                }));
        check("partial remove keeps the entry", "1",
                safe(() -> {
                    SupplyCrate crate = stocked();
                    crate.remove("rope", 2);
                    return String.valueOf(crate.countOf("rope"));
                }));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

