public class SupplyCrate {

    private final int capacity;
    private final java.util.Map<String, Integer> items = new java.util.HashMap<>();

    public SupplyCrate(int capacity) {
        this.capacity = capacity;
    }

    public int getCapacity() {
        return capacity;
    }

    public int totalUnits() {
        int total = 0;
        for (int count : items.values()) {
            total += count;
        }
        return total;
    }

    public int remainingSpace() {
        return capacity - totalUnits();
    }

    public int countOf(String name) {
        Integer count = items.get(name);
        return count == null ? 0 : count;
    }

    public boolean add(String name, int quantity) {
        if (name == null || quantity <= 0) {
            return false;
        }
        if (quantity > remainingSpace()) {
            return false;
        }
        items.put(name, countOf(name) + quantity);
        return true;
    }

    public boolean remove(String name, int quantity) {
        if (name == null || quantity <= 0) {
            return false;
        }
        int current = countOf(name);
        if (quantity > current) {
            return false;
        }
        if (quantity == current) {
            items.remove(name);
        } else {
            items.put(name, current - quantity);
        }
        return true;
    }

    public java.util.List<String> itemNames() {
        java.util.List<String> names = new java.util.ArrayList<>(items.keySet());
        java.util.Collections.sort(names);
        return names;
    }
}
